<?php if(!defined('ABSPATH')){exit;} get_header(); ?><main id="main" class="wrap"><section class="content"><h1><?php echo esc_html(is_archive()?get_the_archive_title():'記事'); ?></h1><?php if(have_posts()): while(have_posts()):the_post(); ?><article><h2><a href="<?php echo esc_url(get_permalink()); ?>"><?php echo esc_html(get_the_title()); ?></a></h2><div><?php echo wp_kses_post(apply_filters('the_content',get_the_content())); ?></div><?php if(get_post_type()==='works'): ?><dl><?php foreach(array('technology'=>'使用技術','period'=>'制作期間','role'=>'担当範囲') as $key=>$label): ?><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html(get_post_meta(get_the_ID(),'_tanzan_'.$key,true)); ?></dd><?php endforeach; ?></dl><?php endif; ?></article><?php endwhile; the_posts_pagination(); else: ?><p>記事はありません。</p><?php endif; ?></section></main><?php get_footer(); ?>